import numpy as np

image = np.array([
    [1, 2, 3, 0, 1],
    [4, 5, 6, 1, 2],
    [7, 8, 9, 2, 3],
    [1, 1, 1, 1, 1],
    [0, 2, 4, 6, 8],
])

filters = {
    "vertical_edge": np.array([[1, 0, -1], [1, 0, -1], [1, 0, -1]]),
    "horizontal_edge": np.array([[1, 1, 1], [0, 0, 0], [-1, -1, -1]]),
}  # already covered as one filter, one feature map in this topic

output_size = image.shape[0] - 3 + 1
feature_maps = {}

for name, filt in filters.items():
    fmap = np.zeros((output_size, output_size))
    for i in range(output_size):
        for j in range(output_size):
            region = image[i:i + 3, j:j + 3]
            fmap[i, j] = np.sum(region * filt)
    feature_maps[name] = fmap
    print(f"Feature map from the '{name}' filter:\n{fmap}\n")

print(f"Total feature maps produced: {len(feature_maps)}, already covered as one filter, one feature map in this topic")
